PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- ---------------------------------------------------------------------------
-- 1) Catálogo de unidades de medida (recria os registros do catálogo)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS UnidadesMedida (
    Id INTEGER NOT NULL CONSTRAINT PK_UnidadesMedida PRIMARY KEY AUTOINCREMENT,
    Nome TEXT NOT NULL,
    Sigla TEXT NULL,
    AplicavelProduto INTEGER NOT NULL,
    AplicavelMedicamento INTEGER NOT NULL,
    AplicavelInsumo INTEGER NOT NULL,
    Ativa INTEGER NOT NULL,
    DataHoraCriacao TEXT NOT NULL,
    DataHoraAtualizacao TEXT NOT NULL,
    EditadorPor TEXT NOT NULL,
    IsDeleted INTEGER NOT NULL
);

DELETE FROM UnidadesMedida;

-- ---------------------------------------------------------------------------
-- 2) Limpeza dos dados de estoque / itens / histórico
-- ---------------------------------------------------------------------------
DELETE FROM MovimentacoesEstoque;
DELETE FROM RetiradaEstoque;
DELETE FROM TransferenciasEstoqueItens;
DELETE FROM TransferenciasEstoque;
DELETE FROM ItensEstoque;
DELETE FROM ItensNivelEstoque;
DELETE FROM ContadoresLote;
DELETE FROM Produtos;
DELETE FROM Medicamentos;
DELETE FROM Insumos;
DELETE FROM ItensBase;

DELETE FROM sqlite_sequence WHERE name IN (
  'ItensBase','MovimentacoesEstoque','RetiradaEstoque',
  'TransferenciasEstoque','TransferenciasEstoqueItens','UnidadesMedida'
);

